#include "mgt/a100_bf16_policy.hpp"

#include <algorithm>
#include <array>

namespace {
template<class T> bool OneOf(T v, std::initializer_list<T> xs) { return std::find(xs.begin(),xs.end(),v)!=xs.end(); }
bool Nonzero(const std::array<std::uint8_t,32>& x) { return std::any_of(x.begin(),x.end(),[](auto b){return b!=0;}); }
void U32(std::vector<std::uint8_t>& o,std::uint32_t v){for(int i=0;i<4;++i)o.push_back(static_cast<std::uint8_t>(v>>(8*i)));}
void U64(std::vector<std::uint8_t>& o,std::uint64_t v){for(int i=0;i<8;++i)o.push_back(static_cast<std::uint8_t>(v>>(8*i)));}
std::uint32_t R(std::uint32_t x,int n){return (x>>n)|(x<<(32-n));}
std::array<std::uint8_t,32> Sha256(std::vector<std::uint8_t> d){
 const std::uint32_t k[64]={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};
 std::uint64_t bits=d.size()*8ULL;d.push_back(0x80);while(d.size()%64!=56)d.push_back(0);for(int i=7;i>=0;--i)d.push_back(static_cast<std::uint8_t>(bits>>(8*i)));
 std::uint32_t h[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
 for(std::size_t off=0;off<d.size();off+=64){std::uint32_t w[64]{};for(int i=0;i<16;++i)w[i]=(std::uint32_t(d[off+4*i])<<24)|(std::uint32_t(d[off+4*i+1])<<16)|(std::uint32_t(d[off+4*i+2])<<8)|d[off+4*i+3];for(int i=16;i<64;++i){auto a=R(w[i-15],7)^R(w[i-15],18)^(w[i-15]>>3),b=R(w[i-2],17)^R(w[i-2],19)^(w[i-2]>>10);w[i]=w[i-16]+a+w[i-7]+b;}auto a=h[0],b=h[1],c=h[2],e0=h[3],e=h[4],f=h[5],g=h[6],z=h[7];for(int i=0;i<64;++i){auto s1=R(e,6)^R(e,11)^R(e,25),ch=(e&f)^(~e&g),t1=z+s1+ch+k[i]+w[i],s0=R(a,2)^R(a,13)^R(a,22),maj=(a&b)^(a&c)^(b&c),t2=s0+maj;z=g;g=f;f=e;e=e0+t1;e0=c;c=b;b=a;a=t1+t2;}h[0]+=a;h[1]+=b;h[2]+=c;h[3]+=e0;h[4]+=e;h[5]+=f;h[6]+=g;h[7]+=z;}
 std::array<std::uint8_t,32> o{};for(int i=0;i<8;++i)for(int j=0;j<4;++j)o[4*i+j]=static_cast<std::uint8_t>(h[i]>>(24-8*j));return o;
}
}

mgt::Status mgt::ValidateA100Bf16Policy(const A100Bf16Policy& p){
 if(p.schema_version!=1||!OneOf(p.linear,{A100LinearBackend::kCublasLtBf16,A100LinearBackend::kCutlassBf16})||!OneOf(p.input_forward,{A100InputForwardBackend::kGatherFromBf16Table,A100InputForwardBackend::kPositionTiledBf16Gemm})||p.input_grad!=A100InputGradBackend::kPositionTiledBf16Gemm||!OneOf(p.batch_norm,{A100BatchNormBackend::kStridedFp32Reference,A100BatchNormBackend::kRowTiledFp32StatsBf16Output,A100BatchNormBackend::kCutlassPartialMomentsBf16})||!OneOf(p.weight_reduce,{A100WeightReduceBackend::kSectionedReference,A100WeightReduceBackend::kTailPlusInputTilesOverlap})||!OneOf(p.graph,{A100GraphBackend::kDisabled,A100GraphBackend::kComputeAndBn,A100GraphBackend::kFullMultistream})||!OneOf(p.xhat_storage,{A100XhatStorage::kFp32,A100XhatStorage::kBf16})||!OneOf(p.dw_dx_schedule,{A100DwDxSchedule::kSerial,A100DwDxSchedule::kConcurrentProtected})||!OneOf(p.input_grad_reduction,{A100InputGradReduction::kOneContiguousSum,A100InputGradReduction::kPositionTiledSums})||!OneOf(p.input_tile_materialization,{A100InputTileMaterialization::kExplicitBf16OneHot,A100InputTileMaterialization::kImplicitCutlassIterator})||!OneOf(p.bn_collective,{A100BnCollectiveBackend::kNcclHostAllReduce,A100BnCollectiveBackend::kNcclDeviceLsa})||!OneOf(p.input_positions_per_tile,{8u,12u,16u,24u,32u,48u,56u,64u,72u})||!OneOf(p.bn_row_chunk,{256u,512u,1024u})||!OneOf(p.bn_feature_tile,{32u,64u})||!OneOf(p.dz_ring_slots,{2u,3u,4u})||!OneOf(p.padded_rows_multiple,{1u,16u,32u})||!OneOf(p.lt_workspace_bytes,{std::uint64_t{16}<<20,std::uint64_t{32}<<20,std::uint64_t{64}<<20,std::uint64_t{128}<<20,std::uint64_t{256}<<20})||!Nonzero(p.algorithm_table_sha256))return Status::kInvalidConfig;return Status::kOk;
}
mgt::Status mgt::CanonicalSerializeA100Bf16Policy(const A100Bf16Policy& p,std::vector<std::uint8_t>* out){
 if(!out||ValidateA100Bf16Policy(p)!=Status::kOk)return Status::kInvalidConfig;out->clear();const std::uint8_t tag[]={'M','G','T','A','1','0','0','P'};out->insert(out->end(),std::begin(tag),std::end(tag));U32(*out,p.schema_version);U32(*out,(std::uint32_t)p.linear);U32(*out,(std::uint32_t)p.input_forward);U32(*out,(std::uint32_t)p.input_grad);U32(*out,(std::uint32_t)p.batch_norm);U32(*out,(std::uint32_t)p.weight_reduce);U32(*out,(std::uint32_t)p.graph);U32(*out,(std::uint32_t)p.xhat_storage);U32(*out,(std::uint32_t)p.dw_dx_schedule);U32(*out,(std::uint32_t)p.input_grad_reduction);U32(*out,(std::uint32_t)p.input_tile_materialization);U32(*out,(std::uint32_t)p.bn_collective);U32(*out,p.input_positions_per_tile);U32(*out,p.bn_row_chunk);U32(*out,p.bn_feature_tile);U32(*out,p.dz_ring_slots);U32(*out,p.padded_rows_multiple);U64(*out,p.lt_workspace_bytes);out->insert(out->end(),p.algorithm_table_sha256.begin(),p.algorithm_table_sha256.end());return Status::kOk;
}
mgt::Status mgt::CanonicalA100Bf16PolicySha256(const A100Bf16Policy& p,std::string* out){if(!out)return Status::kInvalidConfig;std::vector<std::uint8_t>b;if(CanonicalSerializeA100Bf16Policy(p,&b)!=Status::kOk)return Status::kInvalidConfig;const auto d=Sha256(std::move(b));const char* h="0123456789abcdef";out->resize(64);for(std::size_t i=0;i<32;++i){(*out)[2*i]=h[d[i]>>4];(*out)[2*i+1]=h[d[i]&15];}return Status::kOk;}
mgt::Status mgt::CanonicalBytesSha256(const std::vector<std::uint8_t>& bytes,std::string* out){if(!out)return Status::kInvalidConfig;const auto d=Sha256(bytes);const char* h="0123456789abcdef";out->resize(64);for(std::size_t i=0;i<32;++i){(*out)[2*i]=h[d[i]>>4];(*out)[2*i+1]=h[d[i]&15];}return Status::kOk;}
